 i.resolving=false;i.preferencesPending=true;ck(read("pending-preferences").find("pending settings status")!=std::string::npos&&desktop::metronomeFaultGuidance(i).find("Choose Finish")==std::string::npos,"Finish includes actual preference guard");i={};i.preferencesPending=true;i.canConnect=true;ck(read("unowned-settings").find("Choose Connect")==std::string::npos,"pending original settings blocks replacement");i={};i.pendingOutcome=true;i.canConnect=true;ck(read("pending-outcome").find("Waiting")!=std::string::npos,"unresolved outcome cannot become unowned Connect");
