 juce::ScopedJuceInitialiser_GUI gui;desktop::MetronomeView v;desktop::MetronomeViewTestAccess::stopTimer(v);v.setSize(920,680);auto settings=v.settings();settings.numerator=7;settings.denominator=8;settings.styles={metronome::Style::Accent,metronome::Style::Normal,metronome::Style::Silent,metronome::Style::Normal,metronome::Style::Accent,metronome::Style::Normal,metronome::Style::Silent};settings.subdivision=3;settings.ramp=metronome::Ramp{true,2,3,90};ck(v.applySettings(settings),"representative existing settings applied while stopped");v.service();const auto encoded=metronome::encodeSettings(v.settings());desktop::MetronomeViewTestAccess::seed(v);const auto identity=desktop::MetronomeViewTestAccess::identity(v);
